}
pub fn _csv_build(w: *const _CsvWriter) []const u8 { return w.buf.items; }
pub const TcpConn = struct { stream: std.Io.net.Stream };
pub fn _tcp_connect(host: []const u8, port: u16) ?TcpConn {
