    var _rb: [1]u8 = undefined;
    var _rd = conn.stream.reader(_io, &_rb);
    while (true) {
        const _b = _rd.interface.takeByte() catch break;
        if (_b == '\n') break;
        if (_b != '\r') _buf.append(std.heap.page_allocator, _b) catch break;
